def main():
    import source_compiler as compiler
    from destructuring_metadata import nodes
    ROOT=compiler.ROOT;types=compiler.types
    before=types.syntax_validation.implementation_fingerprint()
    frontend=types.Worker([str(types.PHP),'-n','-d','extension='+str(ROOT/'.tools/php-file.so'),str(ROOT/'frontend/worker.php')])
    adapter=types.Worker([str(ROOT/'_build/default/adapter/main.exe'),str(ROOT)])
    observer=importlib.machinery.SourceFileLoader('omission_observer',str(ROOT/'bin/php-semantics')).load_module()
    out=(ROOT/'.tools/array-omission-probes').resolve();out.mkdir(exist_ok=True)
    fixtures=[];records=[];resume_assertions=0
    try:
        for name,source in CASES.items():
            path=out/(name+'.php');path.write_bytes(source)
            parsed=frontend.request({'op':'parse','source':base64.b64encode(source).decode()});assert parsed['accepted'],parsed
            checked=adapter.request({'op':'check','ast':parsed['ast'],'fixture':True})
            command=[str(types.PHP),'-n',*types.FLAGS,str(path)]
            native=subprocess.run(command,capture_output=True,env=types.ENV,timeout=10)
            lint=subprocess.run(command[:-1]+['-l',str(path)],capture_output=True,env=types.ENV,timeout=10)
            executed=adapter.request({'op':'execute','ast':checked['ast'],'steps':10000,'filename':base64.b64encode(str(path).encode()).decode()})
            got=observer.observe(executed['state'],str(path))
            assert (got['exit_status'],got['stdout'],got['stderr'])==(native.returncode,base64.b64encode(native.stdout).decode(),base64.b64encode(native.stderr).decode()),(name,got,native.stdout,native.stderr)
            i=len(fixtures)
            body=f'dec $case{i}() : bool\ndef $case{i}() = true\n  -- if P = $ppstart(91, {checked["fixture"]}, {types.byte_expr(str(path))})\n  -- if $pptrace(P) = '+compiler.context.expected_events(compiler.context.events(lint),path)+'\n'
            cast_facts={'cast-int-finite':'(PINT 1)','cast-int-range':'eps','cast-int-prefix':'(PINT 12)','cast-bool-nan':'eps','cast-float-nan':'eps','cast-string-float':'eps','cast-string-array':'eps','cast-string-int':'(PSTRING ([49,50]))','cast-array-null':'(PARRAY n_cast)','cast-array-value':'(PARRAY n_cast)','cast-array-array':'(PARRAY n_cast)','cast-object':'eps'}
            if name in cast_facts:
                cast_path='[PCINDEX 0, PCFIELD 0, PCFIELD 0, PCINDEX 1, PCFIELD 1]'
                body+='  -- if $pffact(P.FOLD.FACTS, '+cast_path+') = '+cast_facts[name]+'\n  -- if P.FOLD.MEMORY.EVENTS = eps\n'
                if name=='cast-array-array':body+='  -- if $pffact(P.FOLD.FACTS, '+cast_path+' ++ [PCFIELD 0]) = (PARRAY n_cast)\n'
            if name.startswith('skipped-'):
                body+='  -- if P.COMPLETION = PPCNORMAL\n  -- if S_initial = $php_run('+checked['fixture']+', 0, '+json.dumps(base64.b64encode(str(path).encode()).decode())+')\n  -- if S_initial.COMPLETION = BUDGET\n  -- if S = S_initial[.COMPLETION = NORMAL]\n  -- if S_out = $drive(S, 10000)\n'
                for budget in range(61):
                    body+=f'  -- if S_budget{budget} = $drive(S, {budget})\n  -- if $drive(S_budget{budget}[.COMPLETION = NORMAL], 10000) = S_out\n  -- if S_budget{budget}.CODE = S.CODE\n  -- if S_budget{budget}.POOLS = S.POOLS\n  -- if $heap_valid($heap_graph(S_budget{budget}))\n'
                    resume_assertions+=5
            fixtures.append(body)
            records.append({'id':name,'source_base64':base64.b64encode(source).decode(),'checked_ast_sha256':hashlib.sha256(json.dumps(checked['ast'],sort_keys=True).encode()).hexdigest(),'native_command':command,'native_status':native.returncode,'native_stdout':base64.b64encode(native.stdout).decode(),'native_stderr':base64.b64encode(native.stderr).decode(),'observation':got})
        for name,source in PENDING_FOLDS.items():
            ast=frontend.request({'op':'parse','source':base64.b64encode(source).decode()})['ast']
            checked=adapter.request({'op':'check','ast':ast,'fixture':True});i=len(fixtures)
            message='constant class-name resolution' if name=='sweep-class-name-literal' else 'constant class-constant lookup'
            fixtures.append(f'dec $case{i}() : bool\ndef $case{i}() = true\n  -- if P = $ppstart(91, {checked["fixture"]}, [120])\n  -- if P.COMPLETION = PPCABRUPT (UNSUPPORTED "{message}")\n')
        context_checks=0
        for source,kind in [(b'<?php [\n,\n];','ordinary'),(b'<?php [1,\n[\n,\n]];','nested'),(b'<?php false && [\n,\n];','skipped'),(b'<?php ["a"."b",,];','concat')]:
            ast=frontend.request({'op':'parse','source':base64.b64encode(source).decode()})['ast']
            for value in (None,0,-1,91):
                edited=copy.deepcopy(ast)
                field='concatExprLine' if kind=='concat' else 'arrayFirstHoleLine'
                target=next(n for n in nodes(edited,'Expr_BinaryOp_Concat' if kind=='concat' else 'Expr_Array') if field in n['meta'])
                if value is None:target['meta'].pop(field)
                else:target['meta'][field]={'int':str(value)}
                checked=adapter.request({'op':'check','ast':edited,'fixture':True});i=len(fixtures)
                if kind=='skipped':expected='PPCNORMAL'
                elif kind=='nested' or value==91:expected='PPCABRUPT (STATICERROR "Cannot use empty array elements in arrays" '+str(1 if kind=='nested' else value)+')'
                else:expected='PPCABRUPT (UNSUPPORTED "missing ordinary compiler line")'
                fixtures.append(f'dec $case{i}() : bool\ndef $case{i}() = true\n  -- if P = $ppstart(91, {checked["fixture"]}, [120])\n  -- if P.COMPLETION = {expected}\n');context_checks+=1
        for source,kind,bare in [(b'<?php [yield\n,,];','Expr_Yield',True),(b'<?php [exit\n,,];','Expr_Exit',True),(b'<?php [exit(\n),,];','Expr_Exit',False),(b'<?php [exit(1\n),,];','Expr_Exit',False)]:
            ast=frontend.request({'op':'parse','source':base64.b64encode(source).decode()})['ast']
            for value in (None,0,-1,91):
                edited=copy.deepcopy(ast);target=next(nodes(edited,kind))
                if value is None:target['meta'].pop('nullaryExprLine',None)
                else:target['meta']['nullaryExprLine']={'int':str(value)}
                checked=adapter.request({'op':'check','ast':edited,'fixture':True});i=len(fixtures)
                expected=('PPCABRUPT (UNSUPPORTED "missing ordinary compiler line")' if value!=91 else 'PPCABRUPT (STATICERROR "Cannot use empty array elements in arrays" 91)') if bare else 'PPCABRUPT (STATICERROR "Cannot use empty array elements in arrays" 2)'
                fixtures.append(f'dec $case{i}() : bool\ndef $case{i}() = true\n  -- if P = $ppstart(91, {checked["fixture"]}, [120])\n  -- if P.COMPLETION = {expected}\n');context_checks+=1
        for source,kind,field,active in [(b'<?php [clone $x\n,,];','Expr_Clone','cloneExprLine',True),(b'<?php [clone($x)\n,,];','Expr_Clone','cloneExprLine',True),(b'<?php [exit(status:1\n),,];','Expr_FuncCall','endLine',True),(b'<?php [\\exit(status:1\n),,];','Expr_FuncCall','endLine',False),(b'<?php [namespace\\clone($x\n),,];','Expr_FuncCall','endLine',False)]:
            ast=frontend.request({'op':'parse','source':base64.b64encode(source).decode()})['ast']
            for value in (None,0,-1,91):
                edited=copy.deepcopy(ast);target=next(nodes(edited,kind))
                if value is None:target['meta'].pop(field)
                else:target['meta'][field]={'int':str(value)}
                checked=adapter.request({'op':'check','ast':edited,'fixture':True});i=len(fixtures)
                expected=('PPCABRUPT (UNSUPPORTED "missing ordinary compiler line")' if value!=91 else 'PPCABRUPT (STATICERROR "Cannot use empty array elements in arrays" 91)') if active else 'PPCABRUPT (STATICERROR "Cannot use empty array elements in arrays" 1)'
                fixtures.append(f'dec $case{i}() : bool\ndef $case{i}() = true\n  -- if P = $ppstart(91, {checked["fixture"]}, [120])\n  -- if P.COMPLETION = {expected}\n');context_checks+=1
        for source in [b'<?php [exit\n,,];',b'<?php [exit(\n),,];']:
            ast=frontend.request({'op':'parse','source':base64.b64encode(source).decode()})['ast']
            for start,end in [(None,None),(-1,-1),(-2,-1),(9,2)]:
                edited=copy.deepcopy(ast);target=next(nodes(edited,'Expr_Exit'))
                for field,value in [('startTokenPos',start),('endTokenPos',end)]:
                    if value is None:target['meta'].pop(field)
                    else:target['meta'][field]={'int':str(value)}
                checked=adapter.request({'op':'check','ast':edited,'fixture':True});i=len(fixtures)
                fixtures.append(f'dec $case{i}() : bool\ndef $case{i}() = true\n  -- if P = $ppstart(91, {checked["fixture"]}, [120])\n  -- if P.COMPLETION = PPCABRUPT (UNSUPPORTED "missing ordinary compiler line")\n');context_checks+=1
        ast=frontend.request({'op':'parse','source':base64.b64encode(b'<?php [,$x,,"k"=>$y];').decode()})['ast']
        checked=adapter.request({'op':'check','ast':ast,'fixture':True});expected=[]
        for j,node in enumerate(ast['program']):expected.extend(compiler.occurrences.expected(node,[('INDEX',j)]))
        paths=[path for path,node in expected]
        for index in (1,3):assert [('INDEX',0),('FIELD',0),('FIELD',0),('INDEX',index),('FIELD',1)] in paths
        i=len(fixtures);fixtures.append(f'dec $case{i}() : bool\ndef $case{i}() = true\n  -- if $pcsource(91, {checked["fixture"]}).OCCURRENCES = {compiler.occurrences.occurrence_term(expected)}\n');context_checks+=1
        i=len(fixtures);fixtures.append(f'dec $case{i}() : bool\ndef $case{i}() = true\n  -- if $drive($initial_state(NORMAL)[.TODO = [ARRAY_NEXT 0 ([ABSENT])]], 1).COMPLETION = UNSUPPORTED "uncompiled ordinary array omission"\n');context_checks+=1
    finally:frontend.close();adapter.close()
    fixture=out/'compiler.watsup';fixture.write_text(compiler.PREFIX+'\n'.join(fixtures)+'\ndec $main() : bool\ndef $main() = true\n'+''.join(f'  -- if $case{i}()\n' for i in range(len(fixtures))))
    run=subprocess.run([str(ROOT/'tests/semantics/_build/default/numeric_runner.exe'),*map(str,compiler.SPECS),str(fixture)],capture_output=True,text=True,timeout=180)
    assert run.returncode==0 and run.stdout.strip()=='true',(run.stdout,run.stderr)
    assert before==types.syntax_validation.implementation_fingerprint(),'omission inputs changed'
    report={'fingerprint':before,'result':'pass','sources':len(records),'resume_assertions':resume_assertions,'context_checks':context_checks,'cast_fact_checks':25,'pending_fold_boundaries':len(PENDING_FOLDS),'records':records}
    (ROOT/'coverage/semantics/array-omissions.json').write_text(json.dumps(report,indent=2)+'\n')
    print(len(records),'exact source observations/compiler lints;',resume_assertions,'dense resumption assertions;',context_checks,'context/occurrence checks')
